import { sourceMeta } from "@ujc/core";
import type { SelectOption } from "./fuzzy-select";
import { cx } from "../cx";

/**
 * Brand marks for job sources. The images live in ../source-icons.css (generated by
 * scripts/build-source-icons.mjs from ../assets/sources and simple-icons; origins in
 * ../assets/sources/README.md) as data: URIs, so every mark ships once per stylesheet, never once
 * per row, and nothing is fetched at runtime.
 *
 * `tile: true` = the mark has no background of its own and sits on a white tile (dark-mode safe).
 */
export const SOURCE_ICONS = {
  linkedin: { label: "LinkedIn", tile: false },
  seek: { label: "Seek", tile: true },
  arc: { label: "Arc", tile: false },
  lever: { label: "Lever", tile: false },
  ashby: { label: "Ashby", tile: false },
  remotive: { label: "Remotive", tile: false },
  weworkremotely: { label: "We Work Remotely", tile: false },
  himalayas: { label: "Himalayas", tile: true },
  adzuna: { label: "Adzuna", tile: true },
  glassdoor: { label: "Glassdoor", tile: true },
  greenhouse: { label: "Greenhouse", tile: true },
  upwork: { label: "Upwork", tile: true },
  ycombinator: { label: "YC Work at a Startup", tile: false },
} as const satisfies Record<string, { label: string; tile: boolean }>;

export type SourceIconId = keyof typeof SOURCE_ICONS;

// Other spellings of the same site (live search uses "wwr"; deep links use the site's label).
const ALIASES: Record<string, SourceIconId> = {
  wwr: "weworkremotely",
  workatastartup: "ycombinator",
  yc: "ycombinator",
};

/** The icon id for a source id, alias or label ("wwr", "We Work Remotely"), or null. */
export function sourceIconId(source: string): SourceIconId | null {
  const key = source.trim().toLowerCase();
  if (key in SOURCE_ICONS) return key as SourceIconId;
  if (key in ALIASES) return ALIASES[key];
  const byLabel = (Object.keys(SOURCE_ICONS) as SourceIconId[]).find((id) => SOURCE_ICONS[id].label.toLowerCase() === key);
  return byLabel ?? null;
}

export type SourceIconSize = 12 | 14 | 16 | 20;

export interface SourceIconProps {
  /** Source id (`job.source`), alias ("wwr") or label. */
  source: string;
  size?: SourceIconSize;
  /**
   * Accessible name. Default: the source's name. Pass `decorative` instead when the name is
   * already written next to the icon, so screen readers don't hear it twice.
   */
  label?: string;
  decorative?: boolean;
  className?: string;
}

/**
 * A job source's official mark (LinkedIn's "in", Himalayas' mountains...) as a small square.
 * Unknown sources render nothing — callers always show the name as text too.
 */
export function SourceIcon({ source, size = 16, label, decorative = false, className }: SourceIconProps) {
  const id = sourceIconId(source);
  if (!id) return null;
  const name = label ?? SOURCE_ICONS[id].label;
  return (
    <span
      data-source={id}
      data-tile={SOURCE_ICONS[id].tile ? "" : undefined}
      {...(decorative ? { "aria-hidden": true } : { role: "img", "aria-label": name, title: name })}
      style={{ width: size, height: size }}
      className={cx("ujc-source-icon", className)}
    />
  );
}

/** Icon + name, the default way to show a source wherever there's room for the word. */
export function SourceLabel({
  source,
  size = 14,
  className,
}: {
  source: string;
  size?: SourceIconSize;
  className?: string;
}) {
  return (
    <span className={cx("inline-flex min-w-0 items-center gap-1.5", className)}>
      <SourceIcon source={source} size={size} decorative />
      <span className="truncate">{sourceMeta(source).label}</span>
    </span>
  );
}

/** A select option for a source, with its mark (FuzzySelect renders `icon` in the row and trigger). */
export function sourceSelectOption(source: string, size: SourceIconSize = 16): SelectOption {
  return {
    value: source,
    label: sourceMeta(source).label,
    keywords: source,
    icon: <SourceIcon source={source} size={size} decorative />,
  };
}
